"""Development notices with the shared compact Corporate-style shell."""
from pathlib import Path
from html import escape
import sys
sys.path.insert(0,str(Path(__file__).resolve().parent))
from kaavosh_markup import search_form
import json
import subprocess

ROOT=Path(__file__).resolve().parents[1]

def build():
    entries=[
        ('ventures','شتابدهنده زایا','زایا','این بخش در حال طراحی و آماده‌سازی است. جزئیات فعالیت‌ها و مسیرهای همکاری پس از نهایی‌شدن در همین صفحه منتشر می‌شود.'),
        ('developers','پلتفرم توسعه‌دهندگان','توسعه‌دهندگان','زیرساخت و محتوای این بخش در حال آماده‌سازی است. اطلاعات پلتفرم و شیوه‌های مشارکت پس از تکمیل در همین صفحه منتشر می‌شود.')]
    for slug,title,short_label,description in entries:
        context={'url':f'/{slug}/','label':title,'shortLabel':short_label}
        code="const {header,footer}=require('./atlas/tools/build-services-pages');const context=JSON.parse(process.argv[1]);process.stdout.write(JSON.stringify({header:header('home',context),footer:footer(context)}));"
        result=subprocess.run(['node','-e',code,json.dumps(context,ensure_ascii=False)],cwd=ROOT,check=True,capture_output=True,encoding='utf-8')
        shell=json.loads(result.stdout)
        short_description='طراحی مسیرهای رشد و همکاری کسب‌وکارها' if slug=='ventures' else 'آماده‌سازی زیرساخت مشارکت توسعه‌دهندگان'
        form=search_form(action='/corporate/solutions/',home=True).replace(' data-kaavosh','').replace('مفهومی که در جست‌وجوی آن هستید…','جست‌وجوی خدمات شرکتی…').replace('جست‌وجو در اطلس و پژوهش‌ها','جست‌وجو در راهکارهای خدمات شرکتی')
        html=f'''<!DOCTYPE html>
<!-- Generated by tools/build-platform-pages.py; section navigation is shared temporarily. -->
<html lang="fa" dir="rtl"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)} | Private Capital</title><meta name="description" content="{escape(description)}"><meta name="robots" content="noindex,follow"><link rel="canonical" href="https://privatecapital.ir/{slug}/"><link rel="stylesheet" href="/assets/css/style.css"><link rel="stylesheet" href="/assets/css/services.css"><link rel="stylesheet" href="/assets/css/kaavosh.css"><link rel="stylesheet" href="/assets/css/site-footer.css"><link rel="icon" href="/assets/images/favicon.ico"><script src="/assets/js/site-navigation.js" defer></script><script src="/assets/js/services-ui.js" defer></script></head><body class="services-page platform-development">{shell['header']}<main id="main" tabindex="-1"><section class="svc-development container" data-development-status="in-progress"><p class="svc-development-status"><span aria-hidden="true"></span>در حال توسعه</p><h1><span class="svc-quote" aria-hidden="true">“</span>{escape(title)}</h1><p class="svc-development-description"><span class="svc-intro-full">{escape(description)}</span><span class="svc-intro-mobile">{escape(short_description)}</span></p><div class="svc-development-search">{form}</div><a href="/" class="svc-development-back">بازگشت به صفحهٔ اصلی</a></section></main>{shell['footer']}</body></html>
'''
        output=ROOT/slug/'index.html';output.parent.mkdir(parents=True,exist_ok=True)
        output.write_text(html,encoding='utf-8',newline='\n')

if __name__=='__main__':build()
